INSERT INTO `courses` VALUES (4,NULL,'Free MDCAT Mock Test Series',NULL,'🎯 Free MDCAT Mock Test Series\n\nPrepare for MDCAT with our Free MDCAT Mock Test Series, specially designed to help you practice, improve, and build confidence for the real exam. This course includes multiple mock tests covering all MDCAT subjects, including Biology, Chemistry, Physics, English, and Logical Reasoning.\n\nYou will also get access to topic-wise mock tests, subject-wise practice tests, past paper MCQs, and full-length MDCAT mock tests consisting of 100 MCQs based on the latest MDCAT pattern. Every test is created to help you identify your strengths and improve your weak areas..','Prepare for MDCAT with free full-length mock tests designed to match the real exam pattern. Evaluate your performance, identify weak areas, and boost your confidence with detailed explanations and expert analysis—all at no cost.',0,NULL,NULL,'intermediate',NULL,NULL,'/api/uploads/courses/4eaf7512579ecbf04d45da20b8319eb3166005d8e1c2595f.jpg?exp=1785080024&sig=a046ddd13668f2a5c782ad9a57299f314cff111bc9cd1c813e85a480ad52753e','0','0',0,0.00,0,0,5,'2026-07-23 13:44:19','2026-07-26 15:27:29','2026-07-26','2026-08-10','OPEN',NULL,'published',NULL),(5,NULL,'Pricing check ',NULL,'🎯 Free MDCAT Mock Test Series\n\nPrepare for MDCAT with our Free MDCAT Mock Test Series, specially designed to help you practice, improve, and build confidence for the real exam. This course includes multiple mock tests covering all MDCAT subjects, including Biology, Chemistry, Physics, English, and Logical Reasoning.\n\nYou will also get access to topic-wise mock tests, subject-wise practice tests, past paper MCQs, and full-length MDCAT mock tests consisting of 100 MCQs based on the latest MDCAT pattern. Every test is created to help you identify your strengths and improve your weak areas..','Prepare for MDCAT with free full-length mock tests designed to match the real exam pattern. Evaluate your performance, identify weak areas, and boost your confidence with detailed explanations and expert analysis—all at no cost.',0,NULL,NULL,'intermediate',NULL,NULL,'/api/uploads/courses/358a4c1431200c024eb05e21ace80c964f1b23e2d3b4c8bb.jpg?exp=1785079910&sig=fc379ae348fcf514bb10005911b0ce37427abdd0685610789d3aee3658e9b00f','0','0',0,0.00,0,1,5,'2026-07-24 14:14:20','2026-09-01 11:55:41','2026-07-24','2026-07-30','OPEN',NULL,'published',NULL),(6,NULL,'Testing Course',NULL,'This is a testing course  \nThis is a testing course \nThis is a testing course \nThis is a testing course \nThis is a testing course \nThis is a testing course','This is a testing',0,NULL,NULL,'beginner',NULL,NULL,'/api/uploads/courses/4eda7c08989a5f1e46758293bba1d5d2f560d21de191be80.jpg','0','0',0,0.00,0,0,5,'2026-08-17 19:06:06','2026-08-30 16:21:45','2026-08-17','2026-08-19','OPEN',NULL,'published',NULL),(7,NULL,'MDCAT PREPARATION',NULL,'This is an course from mrb calsses for 2026 to 2027',NULL,0,NULL,NULL,'beginner',NULL,NULL,'/api/uploads/courses/2021beaa811c40dec38d53653e9e1cc7dbce7afdb473d814.jpg','0','0',0,0.00,0,1,5,'2026-09-03 05:16:26','2026-09-03 05:16:26',NULL,NULL,'OPEN',NULL,'published',NULL);
