INSERT INTO `tests` VALUES (11,4,'course_locked',0,0,'Biomolecules','Master MDCAT biomolecules with MRB Classes’ test, aligned to the official PMDC syllabus. Sharpen your concepts on carbohydrates, proteins, lipids, and nucleic acids for exam success.',NULL,NULL,NULL,'MDCAT',81,52.00,1,0.00,1,1,1,1,1,0,'private',NULL,'published','2026-07-26 13:00:00','2026-07-27 13:00:00','vertical','all',NULL,0,'biomolecules-11',5,'2026-07-24 09:45:19','2026-07-24 09:47:16',NULL,'subject_wise'),(13,4,'course_locked',0,0,'STOICHIMETRY','Master MDCAT stoichiometry with MRB Classes’ test, strictly based on the PMDC official syllabus. Conquer mole concepts, limiting reactants, and yield calculations with focused practice.',NULL,NULL,NULL,'MDCAT',45,40.00,1,0.00,1,1,1,1,1,0,'public',NULL,'published','2026-07-26 02:00:00','2026-07-26 14:00:00','vertical','all',NULL,0,'stoichimetry-13',5,'2026-07-24 10:26:42','2026-07-24 10:32:15',NULL,'subject_wise'),(14,4,'course_locked',0,0,'Basic Maths and Physics','Master MDCAT basic maths and physics with MRB Classes’ test, aligned to the PMDC official syllabus. Strengthen your vectors, trigonometry, and core mathematical tools for physics success.',NULL,NULL,NULL,'MDCAT',36,29.99,1,0.00,1,1,1,1,1,0,'public',NULL,'published','2026-07-26 03:00:00','2026-07-26 15:00:00','vertical','all',NULL,0,'basic-maths-and-physics-14',5,'2026-07-24 10:41:52','2026-07-24 11:05:11',NULL,'subject_wise'),(15,4,'course_locked',0,0,'Logical Problems and Tenses','Master MDCAT logical problems and tenses with MRB Classes\' test, aligned to the PMDC official syllabus. Build precision in critical thinking and English grammar for top scores.',NULL,NULL,NULL,'MDCAT',18,15.00,1,0.00,0,1,1,1,1,0,'public',NULL,'published','2026-07-26 04:00:00','2026-07-26 16:00:00','vertical','all',NULL,0,'logical-problems-and-tenses-15',5,'2026-07-24 11:12:51','2026-07-24 15:17:36',NULL,'subject_wise'),(65,5,'course_locked',0,0,'testing for sir muzamil',NULL,NULL,NULL,NULL,'MDCAT',18,14.99,1,0.